81	 * Per thread implementation of a TCP stats flusher for statsd.
82	 */
83	class TcpStatsdSink : public Stats::Sink {
84	public:
85	  TcpStatsdSink(const LocalInfo::LocalInfo& local_info, const std::string& cluster_name,
86	                ThreadLocal::SlotAllocator& tls, Upstream::ClusterManager& cluster_manager,
87	                Stats::Scope& scope, const std::string& prefix = getDefaultPrefix());
88	
89	  // Stats::Sink
90	  void flush(Stats::MetricSnapshot& snapshot) override;
91	  void onHistogramComplete(const Stats::Histogram& histogram, uint64_t value) override {
92	    // For statsd histograms are all timers.
93	    tls_->getTyped<TlsSink>().onTimespanComplete(histogram.name(),
94	                                                 std::chrono::milliseconds(value));
95	  }
96	
97	  const std::string& getPrefix() { return prefix_; }
