56	void UdpStatsdSink::flush(Stats::MetricSnapshot& snapshot) {
57	  Writer& writer = tls_->getTyped<Writer>();
58	  for (const auto& counter : snapshot.counters()) {
59	    if (counter.counter_.get().used()) {
60	      writer.write(absl::StrCat(prefix_, ".", getName(counter.counter_.get()), ":", counter.delta_,
61	                                "|c", buildTagStr(counter.counter_.get().tags())));
62	    }
63	  }
64	
65	  for (const auto& gauge : snapshot.gauges()) {
66	    if (gauge.get().used()) {
67	      writer.write(absl::StrCat(prefix_, ".", getName(gauge.get()), ":", gauge.get().value(), "|g",
68	                                buildTagStr(gauge.get().tags())));
69	    }
70	  }
71	}
