160	void TcpStatsdSink::TlsSink::commonFlush(const std::string& name, uint64_t value, char stat_type) {
161	  ASSERT(current_slice_mem_ != nullptr);
162	  // 36 > 1 ("." after prefix) + 1 (":" after name) + 4 (postfix chars, e.g., "|ms\n") + 30 for
163	  // number (bigger than it will ever be)
164	  const uint32_t max_size = name.size() + parent_.getPrefix().size() + 36;
165	  if (current_buffer_slice_.len_ - usedBuffer() < max_size) {
166	    endFlush(false);
167	    beginFlush(false);
168	  }
169	
170	  // Produces something like "envoy.{}:{}|c\n"
171	  // This written this way for maximum perf since with a large number of stats and at a high flush
172	  // rate this can become expensive.
173	  const char* snapped_current = current_slice_mem_;
174	  memcpy(current_slice_mem_, parent_.getPrefix().c_str(), parent_.getPrefix().size());
175	  current_slice_mem_ += parent_.getPrefix().size();
176	  *current_slice_mem_++ = '.';
177	  memcpy(current_slice_mem_, name.c_str(), name.size());
178	  current_slice_mem_ += name.size();
179	  *current_slice_mem_++ = ':';
180	  current_slice_mem_ += StringUtil::itoa(current_slice_mem_, 30, value);
181	  *current_slice_mem_++ = '|';
182	  *current_slice_mem_++ = stat_type;
183	  *current_slice_mem_++ = '\n';
184	
185	  ASSERT(static_cast<uint64_t>(current_slice_mem_ - snapped_current) < max_size);
186	}
